import type { BankQuestion } from "@/lib/bank";

/** Seating Arrangement and Puzzles (Reasoning): 85 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "reason-seating-puzzles-1", "question": "Five friends A, B, C, D and E sit in a row facing north. A sits at the extreme left end, B sits to the immediate right of A, C sits exactly in the middle, and E sits to the immediate left of D. Who sits at the extreme right end?", "options": ["D", "C", "B", "E"], "answer": 0, "explanation": "A takes seat 1, B seat 2 and C seat 3; E must be just left of D, so E is 4 and D is 5. Arrangement (left to right): A, B, C, E, D.", "difficulty": "easy", "source": "SBI Clerk · IBPS Clerk · RRB NTPC"},
  {"id": "reason-seating-puzzles-2", "question": "Seven children sit in a row facing north. Ravi is third from the left end and Mohan is second from the right end. How many children sit between Ravi and Mohan?", "options": ["3", "1", "2", "4"], "answer": 2, "explanation": "Ravi is at seat 3; second from the right of 7 seats is seat 6. Seats 4 and 5 lie between them, so 2 children.", "difficulty": "easy", "source": "SBI Clerk · IBPS Clerk · RRB NTPC"},
  {"id": "reason-seating-puzzles-3", "question": "Four friends P, Q, R and S sit around a square table facing the centre. Q sits to the immediate left of P and R sits opposite P. Who sits to the immediate right of P?", "options": ["S", "R", "Cannot be determined", "Q"], "answer": 0, "explanation": "For people facing the centre, left is clockwise. Clockwise from P: Q, then R (opposite P), then S, so S is the anticlockwise neighbour, i.e. P’s immediate right.", "difficulty": "easy", "source": "SBI Clerk · IBPS Clerk · RRB NTPC"},
  {"id": "reason-seating-puzzles-4", "question": "Five persons A, B, C, D and E live on the five floors of a building, floor 1 being the lowest and floor 5 the top. A lives on the top floor and B immediately below A. C lives on floor 1 and D lives above E. Who lives on floor 3?", "options": ["D", "B", "C", "E"], "answer": 0, "explanation": "A is on 5, B on 4 and C on 1; D and E share floors 2 and 3, and D is above E, so D is on 3 and E on 2.", "difficulty": "easy", "source": "SBI Clerk · IBPS Clerk · RRB NTPC"},
  {"id": "reason-seating-puzzles-5", "question": "Six persons P, Q, R, S, T and U sit in a row facing north. R sits at the extreme left end, S sits to the immediate right of R, and exactly two persons sit between R and T. Q sits to the immediate right of T, and P is not an immediate neighbour of T. Who sits second to the left of Q?", "options": ["T", "P", "S", "U"], "answer": 3, "explanation": "R = 1, S = 2, T = 4, Q = 5. P cannot be 3 (next to T), so P = 6 and U = 3. Arrangement: R, S, U, T, Q, P; second to the left of Q (5) is seat 3, U.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-6", "question": "Six persons A, B, C, D, E and F sit around a circular table facing the centre. A sits opposite D. B sits to the immediate left of A. E sits second to the right of B. C is not an immediate neighbour of B. Who sits to the immediate right of D?", "options": ["E", "B", "F", "C"], "answer": 2, "explanation": "Facing the centre, left is clockwise. Clockwise from A: B, F, D, C, E (E is two places anticlockwise of B; C avoids B so takes the seat between D and E). D’s right (anticlockwise) is F.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-7", "question": "Seven persons J, K, L, M, N, O and P live on floors 1 (lowest) to 7 of a building, one per floor. L lives on the top floor and M on the lowest floor. J lives on an odd-numbered floor above floor 3, and exactly one person lives between J and K, with K below J. O lives immediately above M, and N lives above P. Who lives immediately below J?", "options": ["O", "K", "P", "N"], "answer": 2, "explanation": "J can be 5 or 7, but L has 7, so J = 5 and K = 3. M = 1, O = 2; N and P take 6 and 4 with N higher. Floors 1→7: M, O, K, P, J, N, L, so P is just below J.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-8", "question": "Five boxes A, B, C, D and E are stacked one above another, position 1 being the bottom. Box C is at the top. Exactly two boxes are kept between C and A. B is kept immediately above A, and D is not at the bottom. How many boxes are kept between B and E?", "options": ["3", "0", "1", "2"], "answer": 2, "explanation": "C = 5, so A = 2 and B = 3. D cannot be 1, so D = 4 and E = 1. Stack (bottom to top): E, A, B, D, C; only A lies between B and E.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-9", "question": "Five persons sit in a row facing south. B sits at one end and A sits to the immediate right of B. C sits second to the right of A. E does not sit at an end, and D sits at the remaining seat. Who sits to the immediate left of C?", "options": ["D", "A", "E", "B"], "answer": 2, "explanation": "Facing south, a person’s right is the viewer’s west. Seats west to east: D, C, E, A, B (B at the east end, A just west of B, C two seats further west). C’s left is the seat to its east, E; D is the trap answer for people who treat them as facing north.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-10", "question": "Eight persons sit equally spaced around a circular table facing the centre. A sits third to the left of B, and C sits opposite A. What is the position of C with respect to B?", "options": ["Immediate right", "Second to the right", "Immediate left", "Third to the left"], "answer": 0, "explanation": "Number the seats clockwise with B at 0; facing the centre, left is clockwise, so A is at 3 and C (opposite A) at 7, which is one seat anticlockwise of B, i.e. B’s immediate right.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-11", "question": "Seven persons sit in a row facing north. D sits exactly in the middle, B sits third to the right of D, and F sits to the immediate left of D. How many persons sit to the right of F?", "options": ["5", "2", "4", "3"], "answer": 2, "explanation": "D = 4, B = 7, F = 3. Seats 4 to 7 lie to F’s right, so 4 persons.", "difficulty": "moderate", "source": "SBI Clerk · IBPS Clerk · RRB NTPC"},
  {"id": "reason-seating-puzzles-12", "question": "Six persons P, Q, R, S, T and U sit around a circle facing away from the centre. Q sits to the immediate left of P, S sits to the immediate right of P, R sits opposite Q, and U sits between R and T. Who sits to the immediate right of R?", "options": ["U", "Q", "T", "S"], "answer": 0, "explanation": "Facing outward, left is anticlockwise and right is clockwise. Clockwise from P: S, R, U, T, Q (Q anticlockwise of P, R opposite Q, U between R and T). R’s right (clockwise) is U.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-13", "question": "Eight persons A to H sit in a row facing north. A sits fourth from the left end and three persons sit between A and D. C sits second to the left of D, and H is an immediate neighbour of both A and C. F sits to the immediate left of D. G sits at an extreme end, and B is not an immediate neighbour of A. Who sits exactly midway between B and C?", "options": ["H", "A", "G", "E"], "answer": 1, "explanation": "A = 4, D = 8, C = 6, H = 5, F = 7. G takes the free end seat 1; B cannot be 3 (next to A), so B = 2 and E = 3. Row: G, B, E, A, H, C, F, D; midway between B (2) and C (6) is seat 4, A.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-14", "question": "Eight persons A to H sit around a circular table facing the centre. A sits opposite E, and B sits second to the left of A. F sits to the immediate right of B. C is not an immediate neighbour of A or E. D sits third to the right of C, and G sits to the immediate left of E. Who sits second to the right of G?", "options": ["D", "C", "B", "H"], "answer": 0, "explanation": "Seats clockwise from A = 0 (left is clockwise): B = 2, F = 1, E = 4; C must avoid 1, 3, 5, 7, so C = 6; D = 6 − 3 = 3; G = 5; H = 7. Clockwise: A, F, B, D, E, G, C, H. Two seats anticlockwise of G is D.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-15", "question": "Six persons P, Q, R, S, T and U live on floors 1 (lowest) to 6, one per floor. P lives immediately above U, who lives on an even-numbered floor. Exactly two persons live between U and T, and T lives on a floor below Q. S lives on the top floor, and R lives immediately below U. Who lives immediately above Q?", "options": ["U", "P", "T", "R"], "answer": 3, "explanation": "If U = 2, then P = 3, T = 5 and Q would need floor 6, which S occupies, so U = 4, P = 5, T = 1, R = 3 and Q = 2. Floors 1→6: T, Q, R, U, P, S; R is directly above Q.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-16", "question": "Six persons sit in a row, seats numbered 1 to 6 from west to east; some face north and some face south. A sits in seat 1 facing north, and every two neighbours face opposite directions. E sits at an end. C sits to the immediate right of E. B sits second to the left of C, and D does not sit next to A. Who sits to the immediate left of D?", "options": ["E", "F", "B", "C"], "answer": 3, "explanation": "Alternate facing gives odd seats north, even seats south. E = 6 (south), so its right is west: C = 5 (north); C’s left is west, so B = 3; D avoids seat 2, so D = 4 and F = 2. D faces south, so its left is east: seat 5, C (B is the north-facing trap).", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-17", "question": "Eight persons A to H sit around a square table: four sit at the corners facing the centre and four sit at the middle of the sides facing outside. A sits at a corner. E sits second to the right of A, and B sits to the immediate left of E. C sits third to the left of B, and G sits opposite B. D is an immediate neighbour of C, and F sits at a corner. Who sits to the immediate right of D?", "options": ["E", "C", "B", "G"], "answer": 0, "explanation": "Seats clockwise 0–7 with A = 0 (corners even). Corner sitters face in (left = clockwise), side sitters face out (left = anticlockwise). E = 6, B = 7, C = 7 − 3 = 4, G = 3, D = 5, F = 2, H = 1. Clockwise: A, H, F, G, C, D, E, B. D faces outside, so its right is clockwise: E.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-18", "question": "Six boxes P, Q, R, S, T and U are stacked one above another, position 1 being the bottom. R is third from the top, and exactly one box is kept between R and S. T is kept immediately below S. Q is above U and both are below R. U is kept immediately below P. How many boxes are kept between U and T?", "options": ["4", "1", "2", "3"], "answer": 3, "explanation": "R = 4, so S = 2 or 6. If S = 2, T = 1 and only position 3 is left below R for both Q and U, which fails; so S = 6, T = 5. P, Q, U fill 1–3 with U just below P and Q above U: U = 1, P = 2, Q = 3. Bottom to top: U, P, Q, R, T, S; three boxes lie between U and T.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-19", "question": "A, B, C and D sit in row 1 facing south; P, Q, R and S sit in row 2 facing north, so each person faces one person of the other row. B sits at an end of row 1 and faces Q. S sits to the immediate left of Q. A sits to the immediate right of D. R sits at an end of row 2, and P faces A. Who faces the person sitting to the immediate left of A?", "options": ["P", "Q", "R", "S"], "answer": 3, "explanation": "Number both rows 1–4 west to east. Q faces north, so its left is west; Q cannot be at the west end, so Q = 4, S = 3, R = 1, P = 2. A faces P, so A = 2; A faces south, so its right is west and D = 3; C = 1, B = 4. A’s left is east, seat 3 (D), who faces S.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-20", "question": "Six persons P, Q, R, S, T and U sit around a circle; some face the centre and some face outside. P faces the centre and Q sits to the immediate left of P. R sits opposite P and faces the centre. Q faces outside and S sits to the immediate right of Q. T sits to the immediate left of R. If S faces the centre, who sits second to the left of S?", "options": ["R", "P", "T", "U"], "answer": 2, "explanation": "Seats clockwise with P = 0: Q = 1 (P’s left, clockwise), R = 3, S = 2 (Q faces out, so its right is clockwise), T = 4 (R faces in, left clockwise), U = 5. Clockwise: P, Q, S, R, T, U. S faces in, so two places clockwise from S is T.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-21", "question": "Seven persons J, K, L, M, N, O and P attend a seminar on different days of one week, Monday to Sunday. J attends on Wednesday. Only one person attends between J and L, and L attends after J. N attends immediately after L. K attends before M, and both attend before J. P does not attend on Thursday. Who attends exactly midway between M and N?", "options": ["O", "J", "L", "P"], "answer": 0, "explanation": "J = Wednesday, L = Friday, N = Saturday; K and M fill Monday and Tuesday in that order. P avoids Thursday, so P = Sunday and O = Thursday. M is Tuesday and N Saturday, so the midpoint is Thursday, O.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-22", "question": "Seven persons A to G sit in a row facing north. E sits third from the right end. As many persons sit to the left of E as to the right of B. C sits to the immediate right of B. Two persons sit between C and F. G sits at an extreme end and to the left of D, and D is an immediate neighbour of E. Who sits second to the right of C?", "options": ["F", "E", "D", "A"], "answer": 2, "explanation": "E = 5 with 4 people to its left, so B has 4 to its right: B = 3, C = 4, F = 1 or 7. G must be at seat 1 to have D on its right, so F = 7; D next to E gives D = 6 and A = 2. Row: G, A, B, C, E, D, F; second to the right of C is D.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-23", "question": "Seven persons A to G sit around a circular table facing the centre (no two sit opposite each other). B sits third to the left of A, and C sits second to the right of B. D is an immediate neighbour of A but not of C. E sits to the immediate left of B, and F is not an immediate neighbour of D. Who sits exactly between E and D?", "options": ["F", "B", "G", "A"], "answer": 2, "explanation": "Seats clockwise 0–6 with A = 0 (left = clockwise): B = 3, C = 1, D = 6, E = 4; F avoids 5 (next to D), so F = 2 and G = 5. Clockwise: A, C, F, B, E, G, D; G sits between E and D.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-24", "question": "Five friends P, Q, R, S and T sit in a row facing north, each owning a car of a different colour: red, blue, green, white and black. R sits in the middle. The green car’s owner sits at the extreme right end and Q sits to his immediate left. T sits at an extreme end and owns the red car. P is not an immediate neighbour of R. The blue car’s owner sits to the immediate right of S, and Q does not own the white car. Who owns the white car?", "options": ["Q", "R", "T", "S"], "answer": 3, "explanation": "R = 3, Q = 4; P and T must be at the ends and T (red) cannot be the green owner at seat 5, so T = 1, P = 5 (green), S = 2. R, right of S, owns blue; Q is not white, so Q has black and S white. Row: T-red, S-white, R-blue, Q-black, P-green.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-25", "question": "Some persons sit in a row facing north. A sits fourth from the left end, and exactly two persons sit between A and B, with B to the right of A. B is eighth from the right end. D sits third from the right end and C sits exactly midway between A and D. How many persons sit between B and the person who sits second to the right of C?", "options": ["2", "1", "4", "3"], "answer": 0, "explanation": "A = 4, B = 7, and 7 + 8 − 1 = 14 persons in all. D = 14 − 3 + 1 = 12, so C = (4 + 12)/2 = 8 and the person second to C’s right is at 10. Between seats 7 and 10 sit 8 and 9: 2 persons.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-26", "question": "Eight persons J, K, L, M, N, O, P and Q sit around a circular table facing the centre. M sits third to the right of J. Only one person sits between M and Q when counted clockwise from M. K sits opposite Q and L sits to the immediate left of K. N is not an immediate neighbour of J, and P sits to the immediate right of N. How many of these statements are true? I. O sits to the immediate right of Q. II. N sits second to the left of J. III. L sits opposite P. IV. M is an immediate neighbour of both L and O.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Seats clockwise from J = 0 (left = clockwise): M = 5, Q = 7, K = 3, L = 4; N must be 2 (seat 6 would put P on M), P = 1, O = 6. Clockwise: J, P, N, K, L, M, O, Q. I, II and IV are true; III is false because L (4) is opposite J (0), not P.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-27", "question": "Eight persons A to H live on floors 1 (lowest) to 8, one per floor. D lives on an odd-numbered floor above floor 4, and three persons live between D and G. B lives immediately above G. Only one person lives between B and A, and A lives above B. C lives on the lowest floor and E lives immediately above C. F lives above H. How many of these statements are true? I. Two persons live between H and E. II. F lives immediately above D. III. B lives exactly midway between G and A. IV. G lives immediately below H.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "D = 5 would give G = 1, clashing with C, so D = 7, G = 3, B = 4, A = 6, C = 1, E = 2, and F, H take 8 and 5. Floors 1→8: C, E, G, B, H, A, D, F. I (floors 3, 4 between) and II are true; III is false (midway of 3 and 6 is 4.5) and IV is false.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-28", "question": "Eight persons P, Q, R, K, T, U, V and W sit in a row, seats numbered 1 to 8 from west to east; some face north and some face south. P sits in seat 4 facing north, and R sits second to the right of P. U sits to the immediate left of R, and U and R face opposite directions. K sits at an end facing south, and V sits third to the right of K and faces north. T sits at the west end facing north. W faces south and Q sits to the immediate right of W. Who sits to the immediate left of the person who sits second to the left of U?", "options": ["T", "R", "W", "P"], "answer": 3, "explanation": "R = 6. K must be at seat 8 (south-facing, its right is west) so V = 5; U cannot be 5, so U = 7, meaning R faces south and U north. T = 1; W faces south, its right is west, so Q = 2 and W = 3. U faces north: second to its left is V (5); V faces north, so its immediate left is P (4).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-29", "question": "Eight persons A to H sit around a square table: four sit at the corners facing outside and four at the middle of the sides facing the centre. G sits at a corner. C sits third to the left of G, and A sits opposite C. E sits second to the right of A, and B sits to the immediate right of E. H is not an immediate neighbour of C. D sits at a corner, and F sits to the immediate left of D. Who sits second to the right of F?", "options": ["C", "A", "H", "D"], "answer": 1, "explanation": "Seats clockwise 0–7 with G = 0 (corners even, facing out: left = anticlockwise; sides facing in: left = clockwise). C = 5, A = 1, E = 7, B = 6. D = 2 would put F on A, so D = 4, F = 3, H = 2. Clockwise: G, A, H, F, D, C, B, E. F faces the centre, so its right is anticlockwise: two seats gives A.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-30", "question": "A building has four floors (1 at the bottom to 4 at the top), each with two flats: Flat A on the west and Flat B on the east, with each Flat A directly above the Flat A below it. Eight persons live one per flat. P lives in Flat A of an odd-numbered floor, and T lives in the flat immediately east of P. Q lives on floor 1 in the same type of flat as T, and S lives to the west of Q. N lives directly above Q and M directly above T. O lives directly below P. Which pair lives on the same floor?", "options": ["R and M", "P and M", "S and N", "O and T"], "answer": 0, "explanation": "If P were on floor 1, T and Q would both need flat 1B, so P = 3A, T = 3B, Q = 1B, S = 1A, N = 2B, M = 4B, O = 2A and R = 4A. Floor 4: R, M; floor 3: P, T; floor 2: O, N; floor 1: S, Q.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-31", "question": "Six persons A to F go on trips in six months, January to June, one per month, each to a different city: Pune, Goa, Agra, Ooty, Leh and Kochi. Agra is visited in a 31-day month after February, and C travels in the month immediately after the Agra traveller, in a 30-day month. D goes to Leh after C. B travels in June. A travels immediately after E, and F goes to Agra. Goa is visited in the month with fewer than 30 days, Pune is visited before Goa, and B does not go to Ooty. Who goes to Ooty, and in which month?", "options": ["F, March", "C, June", "C, April", "B, June"], "answer": 2, "explanation": "Agra is March or May; May would put C in June and leave no month for D after C, so Agra = March (F), C = April, D = May (Leh), B = June, E = January, A = February. Goa = February (A), Pune = January (E), and B takes Kochi, leaving Ooty for C in April.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-32", "question": "Eight persons A to H sit around a circle; four face the centre and four face outside. A faces the centre. D sits second to the left of A, and both immediate neighbours of A face outside. F sits opposite A and faces the same direction as A. B sits to the immediate right of F and faces outside. C sits third to the right of B. D faces outside and H sits to the immediate left of D. C faces the centre and E sits to the immediate right of C. How many of these statements are true? I. G sits to the immediate left of A. II. E faces the centre. III. H sits opposite C. IV. Exactly two persons sit between D and F counted clockwise from D.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 0, "explanation": "Seats clockwise from A = 0: D = 2, F = 4, B = 3, C = 6 (B faces out, right = clockwise), H = 1, E = 5, G = 7. Facing centre: A, F, C and so E; facing out: H, D, B, G. Only II is true: A’s left is H, H is opposite E, and only B sits between D and F clockwise.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-33", "question": "Seven boxes P, Q, R, S, T, U and V are stacked one above another, position 1 being the bottom. V is exactly in the middle of the stack, and two boxes are kept between V and R. Q is kept above R. Only one box is kept between R and S, and U is kept immediately above R. P is kept below T, Q is not kept immediately above V, and T is kept immediately below Q. How many of these statements are true? I. P is kept immediately above V. II. Three boxes are kept between U and P. III. R is at the bottom. IV. T is second from the top.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "V = 4 and R = 1 or 7; Q above R forces R = 1, so S = 3, U = 2. P, T, Q fill 5–7 with P below T, Q not at 5 and T just below Q: P = 5, T = 6, Q = 7. Bottom to top: R, U, S, V, P, T, Q. I, III and IV are true; II is false (only S and V lie between U and P).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-34", "question": "Seven persons J, K, L, M, O, P and N sit in a row facing north. K sits third from an end, and only two persons sit between K and N, with N to the right of K. As many persons sit to the right of N as to the left of J. M sits at an extreme end and is not an immediate neighbour of J. P sits to the immediate left of O. If all seven are re-seated in alphabetical order from left to right, how many of them keep their original seats?", "options": ["None", "Three", "One", "Two"], "answer": 0, "explanation": "K = 5 would put N at 8, so K = 3 and N = 6; one person is right of N, so J = 2. M must be at 7, P = 4, O = 5 and L = 1. Original: L, J, K, P, O, N, M; alphabetical: J, K, L, M, N, O, P. No seat holds the same person.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-35", "question": "Six persons A to F sit around a circular table facing the centre, each liking a different fruit: apple, banana, cherry, grape, mango and orange. A likes mango. F likes grape and sits opposite A. C sits second to the right of A, and E sits to the immediate left of C. B is not an immediate neighbour of A, and D sits to the immediate right of B. The cherry lover sits to the immediate left of the grape lover. D likes neither apple nor orange. The orange lover sits to the immediate right of A. Which combination is correct?", "options": ["B – apple – sits opposite D", "E – apple – sits opposite B", "C – orange – sits opposite D", "D – banana – sits opposite C"], "answer": 3, "explanation": "Seats clockwise from A = 0 (left = clockwise): F = 3, C = 4, E = 5, B = 2, D = 1. Cherry is clockwise of F, so C; orange is anticlockwise of A, so E; D takes banana and B apple. Clockwise: A-mango, D-banana, B-apple, F-grape, C-cherry, E-orange; D (1) is opposite C (4).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-36", "question": "Some persons sit around a circular table facing the centre. P is fifth to the left of Q and also seventh to the right of Q. R sits third to the right of P. How many persons sit between R and Q when counted in the direction of R’s left?", "options": ["1", "10", "9", "8"], "answer": 2, "explanation": "5 + 7 = 12 persons. Seats clockwise with Q = 0 (left = clockwise): P = 5, R = 5 − 3 = 2. Moving clockwise (R’s left) from 2 to Q at 0 passes seats 3 to 11: 9 persons; 1 is the count the other way.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-37", "question": "Seven persons A to G live on floors 1 (lowest) to 7, one per floor. G lives on an even-numbered floor above floor 3, and C lives two floors below G. E lives immediately above A. Four persons live between A and F, and F lives above A. B does not live above D. How many of these statements are true? I. D lives immediately below G. II. Exactly two persons live between E and G. III. B lives immediately below A. IV. F lives exactly three floors above C.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "G = 4 would put C on 2 and leave no valid A–F pair, so G = 6, C = 4; A = 2, F = 7 (A = 1 needs F = 6), E = 3; B and D take 1 and 5 with B lower. Floors 1→7: B, A, E, C, D, G, F. All four statements are true.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-38", "question": "Six persons A to F sit in a row facing north, each liking a different subject: Hindi, English, Maths, Physics, History and Biology. D sits at an extreme end, and only two persons sit between D and E. B sits to the immediate right of E. The Maths lover sits to the immediate left of E, and F sits to the immediate left of the Maths lover. C sits at an extreme end and likes Physics. The History lover sits at an extreme end. The English lover sits second to the right of the Maths lover, and F does not like Biology. Who sits second to the left of the Biology lover, and what does that person like?", "options": ["F – Hindi", "A – Maths", "F – Biology", "D – History"], "answer": 0, "explanation": "D = 6 would force F onto C’s seat, so D = 1, E = 4, B = 5, C = 6, Maths = seat 3 (A), F = 2. D likes History, B English (seat 5), F Hindi, E Biology. Row: D-History, F-Hindi, A-Maths, E-Biology, B-English, C-Physics; second left of E is F.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-39", "question": "Six persons L, M, R, O, P and Q sit in a row, seats numbered 1 to 6 from west to east; some face north and some face south. L sits at the west end facing north. O sits third to the right of L. P faces south, sits to the immediate left of O, and faces the same direction as O. Q sits at an end and faces the same direction as L. R sits to the immediate left of M, who faces north. R faces the direction opposite to both of its neighbours. How many persons face north, and who sits to the immediate right of P?", "options": ["Two; O", "Four; Q", "Three; Q", "Three; O"], "answer": 3, "explanation": "O = 4 and faces south like P, so O’s left is east: P = 5. Q = 6 facing north. M faces north, so R (on M’s left, i.e. west) = 2 and M = 3. R’s neighbours L and M face north, so R faces south. North: L, M, Q (three). P faces south, so its right is west: O.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-40", "question": "Five persons V, W, X, Y and Z live on floors 1 (lowest) to 5, one per floor, each liking a different colour: red, blue, green, yellow and white. Y lives on the lowest floor and W immediately above Y. V lives on an even-numbered floor and X lives above V. The person on the top floor likes green. The blue lover lives exactly midway between Y and the green lover. V likes neither red nor yellow, and W does not like yellow. Which combination is correct?", "options": ["X – white – floor 5", "W – red – floor 2", "Z – blue – floor 4", "V – yellow – floor 4"], "answer": 1, "explanation": "Y = 1, W = 2, so V = 4 and X = 5 (green); Z = 3, which is midway between 1 and 5, so Z likes blue. V gets white, W red and Y yellow. Floors 1→5: Y-yellow, W-red, Z-blue, V-white, X-green.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-41", "question": "Six persons P, Q, R, S, T and U sit in a row facing north. Q sits at the extreme right end. T sits third to the left of Q, and P sits to the immediate left of T. U sits to the immediate left of Q, and S does not sit at either end. Who sits between T and U?", "options": ["R", "P", "S", "U"], "answer": 2, "explanation": "Q = 6, T = 3, P = 2, U = 5. S cannot be at an end, so S = 4 and R = 1. Row (left to right): R, P, T, S, U, Q; S sits between T and U.", "difficulty": "easy", "source": "SBI Clerk · IBPS Clerk · RRB NTPC"},
  {"id": "reason-seating-puzzles-42", "question": "Six friends A, B, C, D, E and F sit around a circular table facing the centre. A sits opposite D. B sits to the immediate left of A, and C sits opposite B. E sits to the immediate right of D. Who sits to the immediate right of A?", "options": ["E", "C", "B", "F"], "answer": 3, "explanation": "Facing the centre, left is clockwise. Clockwise from A: B, E, D, C, F. A's right is its anticlockwise neighbour, F.", "difficulty": "easy", "source": "SBI Clerk · IBPS Clerk · RRB NTPC"},
  {"id": "reason-seating-puzzles-43", "question": "Five persons A, B, C, D and E have meetings on five days, Monday to Friday, one per day. C's meeting is on Wednesday and A's is on the day just after C's. E's meeting is on Monday, and B's is not on Friday. Whose meeting is on Friday?", "options": ["D", "B", "A", "C"], "answer": 0, "explanation": "E Monday, C Wednesday, A Thursday. B cannot take Friday, so B takes Tuesday and D Friday.", "difficulty": "easy", "source": "SBI Clerk · IBPS Clerk · RRB NTPC"},
  {"id": "reason-seating-puzzles-44", "question": "Six persons A to F sit around a rectangular table facing the centre: one person at each shorter end and two along each longer side. A and D sit at the two shorter ends. B sits to the immediate left of A, and C sits directly opposite B across the table. F sits to the immediate left of D. Who sits directly opposite F?", "options": ["B", "E", "C", "A"], "answer": 1, "explanation": "Going clockwise (the left of a centre-facing person) from A: B, E, D, F, C. B and E share one long side, F and C the other; B faces C, so E faces F.", "difficulty": "easy", "source": "SBI Clerk · IBPS Clerk · RRB NTPC"},
  {"id": "reason-seating-puzzles-45", "question": "A, B and C sit in one row facing south, and P, Q and R sit in a parallel row facing north, so each person faces one person of the other row. B sits in the middle of the first row and faces P. A sits to the immediate right of B, and Q sits to the immediate right of P. Who faces C?", "options": ["P", "R", "Q", "A"], "answer": 2, "explanation": "Number seats 1–3 west to east. B = 2, P = 2. A faces south, so its right is west: A = 1, C = 3. Q faces north, so its right is east: Q = 3, R = 1. C (3) faces Q.", "difficulty": "easy", "source": "SBI Clerk · IBPS Clerk · RRB NTPC"},
  {"id": "reason-seating-puzzles-46", "question": "Eight seats in a row are numbered 1 to 8 from left to right, and six persons A to F sit on six of them facing north; two seats are vacant. A sits on seat 3 and seat 8 is vacant. Exactly one person sits between A and B, with B to the right of A, and the seat to the immediate right of B is vacant. C sits on seat 1 and D sits to the immediate right of C. E sits somewhere to the right of F. How many persons sit between C and E?", "options": ["3", "4", "5", "2"], "answer": 1, "explanation": "B = 5 (seat 4 is occupied) and seat 6 is vacant. C = 1, D = 2. E and F take seats 4 and 7, with E to the right: F = 4, E = 7. Between seats 1 and 7 sit D, A, F and B (seat 6 is empty): 4 persons.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-47", "question": "Eight persons A to H sit around a circular table facing the centre. C sits second to the right of A, and E sits opposite C. G sits to the immediate left of E, and D sits opposite G. B and H sit next to each other, H to the immediate right of B, and neither of them is an immediate neighbour of A. Who sits to the immediate left of A?", "options": ["G", "D", "H", "F"], "answer": 3, "explanation": "Seats clockwise from A = 0 (left = clockwise): C = 6, E = 2, G = 3, D = 7. Of seats 1, 4 and 5, B and H avoid A's side, so they take 4 and 5 with H anticlockwise of B: B = 5, H = 4, F = 1. A's left (clockwise) is F.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-48", "question": "Seven persons P, Q, R, S, T, U and V live on floors 1 (lowest) to 7, one per floor. S lives on floor 4, and exactly two persons live between S and V, with V above S. Q lives immediately below S. R lives on an odd-numbered floor below Q. P lives on an even-numbered floor above Q, and U lives above T. Who lives immediately above U?", "options": ["P", "V", "S", "T"], "answer": 0, "explanation": "V = 7, Q = 3, R = 1, and P (even, above 3, floor 4 taken) = 6. T and U take 2 and 5 with U higher: T = 2, U = 5. P on floor 6 is just above U.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-49", "question": "Seven persons A to G have appointments on the seven days of a week, Monday to Sunday, one per day. D's appointment is on Thursday, and exactly two persons have appointments between D and B, B after D. G's appointment is the day before D's. Exactly one person's appointment falls between A's and G's, A before G. E's appointment is after D's but before B's, and not on Saturday. C's appointment is not on the day immediately after A's. Whose appointment is on Saturday?", "options": ["F", "E", "C", "A"], "answer": 2, "explanation": "D Thursday, B Sunday, G Wednesday, A Monday, E Friday. Tuesday and Saturday remain; C cannot be on Tuesday (the day after A), so C is on Saturday and F on Tuesday.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-50", "question": "Two parallel rows have five seats each, numbered 1 to 5 from west to east. A, B, C, D and E sit in row 1 facing south; P, Q, R, S and T sit in row 2 facing north, so each person faces one person of the other row. C sits in the middle of row 1, and A sits second to the right of C. R faces A. Q sits third to the right of R, and B faces Q. P sits at an end of row 2. E sits to the immediate left of B, and S sits to the immediate right of R. Who faces D?", "options": ["T", "S", "P", "R"], "answer": 1, "explanation": "Row 1 faces south, so right = west: C = 3, A = 1, R = 1. Row 2 faces north, so right = east: Q = 4, B = 4, P = 5. E is left (east) of B: E = 5, D = 2. S is right (east) of R: S = 2, T = 3. D faces S.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-51", "question": "Six boxes P, Q, R, S, T and U are stacked one above another, position 1 being the bottom. T is fourth from the bottom, and exactly one box is kept between T and Q, Q below T. U is immediately above T. S is neither at the top nor at the bottom, and R is kept above P. How many boxes are kept between R and S?", "options": ["1", "3", "0", "2"], "answer": 3, "explanation": "T = 4, Q = 2, U = 5. Of positions 1, 3 and 6, S takes 3; R above P gives P = 1, R = 6. Between 6 and 3 lie T and U: 2 boxes.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-52", "question": "Six persons A to F sit around a circle facing away from the centre. B sits second to the left of A, and D sits opposite B. C sits to the immediate right of D. E is not an immediate neighbour of A. Who sits opposite F?", "options": ["C", "E", "D", "B"], "answer": 0, "explanation": "Facing outside, left is anticlockwise. Seats clockwise from A = 0: B = 4, D = 1, C = 2 (right = clockwise). E avoids seats 1 and 5, so E = 3 and F = 5. Opposite seat 5 is seat 2, C.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-53", "question": "Five persons P, Q, R, S and T were born in 1982, 1986, 1988, 1995 and 1999, one in each year. Q was born in a leap year, and R is 7 years younger than Q. S is older than Q but is not the eldest. P's age in 2024 is an odd number. Taking ages in 2024, what is the sum of the ages of S and R?", "options": ["63", "71", "67", "65"], "answer": 2, "explanation": "Only 1988 is a leap year, so Q = 1988 and R = 1995. S older than Q but not eldest = 1986. Of 1982 (42) and 1999 (25), P has the odd age: P = 1999, T = 1982. S 38 + R 29 = 67.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-54", "question": "Seven persons J, K, L, M, N, O and P sit in a row facing south. K sits at the west end, and M sits third to the left of K. N sits to the immediate right of M, and O sits second to the left of N. P sits at the east end, and J sits to the immediate right of P. Who sits to the immediate left of L?", "options": ["M", "N", "K", "O"], "answer": 1, "explanation": "Facing south, left is east and right is west. Seats 1–7 west to east: K = 1, M = 4, N = 3, O = 5, P = 7, J = 6, L = 2. L's immediate left is seat 3, N.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-55", "question": "Eight persons A to H sit around a circular table facing the centre. A sits opposite B. C sits second to the left of A, and D sits opposite C. H is an immediate neighbour of both B and C. E is not an immediate neighbour of D, and F sits to the immediate right of A. Who sits third to the left of the person who sits to the immediate right of D?", "options": ["E", "F", "H", "A"], "answer": 3, "explanation": "Seats clockwise from A = 0: B = 4, C = 2, D = 6, H = 3, F = 7; E avoids 5 and 7, so E = 1 and G = 5. Clockwise: A, E, C, H, B, G, D, F. D's right (anticlockwise) is G at 5; third to the left of G is seat 0, A.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-56", "question": "Eight persons A to H live on floors 1 (lowest) to 8, one per floor. C lives on an even-numbered floor above floor 5. Exactly two persons live between C and F, and F lives on an odd-numbered floor. A lives immediately above F. E lives on floor 1. B lives immediately below G. D lives below H but not immediately above E. How many persons live between H and G?", "options": ["2", "3", "4", "1"], "answer": 1, "explanation": "Case C = 6: F = 3, A = 4, so B–G take 7–8 and D, H take 2 and 5 with D = 2, just above E: rejected. Case C = 8: F = 5, A = 6; B–G must be 2–3 (if 3–4, D would be 2), so D = 4, H = 7. Floors 1→8: E, B, G, D, F, A, H, C. Between H (7) and G (3): D, F, A = 3.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-57", "question": "Eight persons P, Q, R, S, T, U, V and W each have a programme on the 12th or the 25th of March, May, July or September of one year; no two programmes share a date. R's programme is on the 25th of a month with 31 days. Exactly two programmes fall between R's and V's, and V's programme is in a month with 30 days. T's programme is immediately before R's. Q's programme is in the same month as V's. W's programme is on the 12th, but not in March. U's programme is after S's, and P's is not in March. Whose programme is on 25 March?", "options": ["U", "S", "P", "T"], "answer": 0, "explanation": "Order: Mar 12, Mar 25, May 12, May 25, Jul 12, Jul 25, Sep 12, Sep 25. V is in September, three places from R (25 Mar/May/Jul), so R = 25 May, V = 12 Sep. T = 12 May, Q = 25 Sep, W = 12 Jul, P = 25 Jul. S and U take March with U later: S = 12 Mar, U = 25 Mar.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-58", "question": "Eight persons A to H sit in a row facing north. B sits third from the right end, and exactly two persons sit between B and E. G sits second to the left of E. As many persons sit between G and E as between B and D, and D does not sit at an end. C sits to the immediate right of B. F is not an immediate neighbour of G, H is not an immediate neighbour of D, and A sits somewhere to the left of H. Who sits third to the right of the person who sits to the immediate right of A?", "options": ["D", "F", "B", "C"], "answer": 2, "explanation": "B = 6, E = 3, G = 1. One person sits between G and E, so D = 4 (8 is an end); C = 7. Seats 2, 5, 8 remain: H cannot be 5 (next to D) or 2 (A must be to its left), so H = 8; F cannot be 2, so F = 5, A = 2. Row: G, A, E, D, F, B, C, H. A's right is E (3); third to the right of E is seat 6, B.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-59", "question": "Six persons P, Q, R, S, T and U sit around a circle; some face the centre and some face outside. P faces the centre, and Q sits to the immediate left of P. S sits opposite P and faces the same direction as Q. T sits second to the right of Q. U sits to the immediate left of S. Exactly three persons face the centre. Who sits to the immediate right of R?", "options": ["U", "P", "T", "S"], "answer": 3, "explanation": "Seats clockwise from P = 0: Q = 1, S = 3. If Q faced outside, its right would be clockwise and T would fall on S's seat, so Q faces the centre and T = 5. S faces the centre too, so U (its left, clockwise) = 4 and R = 2. P, Q and S face the centre, so R, T and U face outside. R's right is therefore clockwise: seat 3, S.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-60", "question": "Seven persons A to G work in an office at seven levels; from the highest: CEO, MD, GM, AGM, Manager, Executive and Clerk, one person per level. D is senior to only three persons. Exactly two persons rank between D and B, and B is junior to F. G is D's immediate senior. E is senior to G but is not the CEO. C is junior to A, and A is not the CEO. How many persons are senior to A?", "options": ["3", "5", "2", "4"], "answer": 3, "explanation": "D is AGM (4th). B is 1st or 7th; being junior to F, B is Clerk. G is GM and E is MD. CEO, Manager and Executive remain for A, C and F; A is not CEO and C is junior to A, so A = Manager, C = Executive, F = CEO. Senior to A: F, E, G, D = 4.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-61", "question": "Six persons P, Q, R, S, T and U were born in 1976, 1981, 1985, 1990, 1996 and 2001, one in each year. S was born in a leap year, and the difference between the ages of S and U is 11 years. Q is older than U. T's age in 2024 is a multiple of 17. R is younger than T. P is not the eldest. Taking ages in 2024, what is the sum of the ages of P and T?", "options": ["77", "82", "73", "71"], "answer": 0, "explanation": "Leap years: 1976 and 1996; only 1996 has a year 11 apart (1985), so S = 1996, U = 1985. Ages in 2024 are 48, 43, 39, 34, 28, 23; only 34 is a multiple of 17, so T = 1990. R younger than T = 2001. Q older than U and P not eldest: Q = 1976, P = 1981. 43 + 34 = 77.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-62", "question": "Five persons J, K, L, M and N live on floors 1 (lowest) to 5, one per floor, and each likes a different colour: red, blue, green, white and black. The person who likes green lives on floor 3, and K lives immediately above that person. Exactly one person lives between K and the person who likes red. J lives on an odd-numbered floor and does not like green. L likes white and does not live on the top floor. M lives above N. J does not like black. Who likes black, and on which floor does that person live?", "options": ["J, floor 5", "K, floor 4", "N, floor 2", "M, floor 3"], "answer": 1, "explanation": "Green = 3, K = 4, red = 2. L (white) cannot be on 2, 3, 4 or 5, so L = 1. J (odd, not green) = 5. M above N: M = 3 (green), N = 2 (red). J is not black, so J likes blue and K black, on floor 4.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-63", "question": "Seven persons A to G sit around a circular table facing the centre. D sits second to the right of A. Only two persons sit between D and F, and F is an immediate neighbour of A. B sits third to the left of F. G sits to the immediate left of D. E sits to the immediate left of C. How many persons sit between B and F when counted clockwise from B?", "options": ["2", "4", "3", "1"], "answer": 2, "explanation": "Seats clockwise from A = 0 (left = clockwise): D = 5. Seats with two persons between them and D are 1 and 2; F next to A gives F = 1. B = 4, G = 6; C and E take 2 and 3 with E clockwise of C. Clockwise: A, F, C, E, B, D, G. From B clockwise: D, G, A, then F, so 3.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-64", "question": "Six persons A to F attend a workshop with six sessions held on Monday, Wednesday and Friday of one week, with a morning and an evening session each day; one person per session. C attends on Wednesday. Exactly one session falls between C's and E's, and E attends an evening session. F attends the session immediately after E's. B does not attend on Friday, and D attends after A. Who attends the Friday morning session?", "options": ["D", "B", "F", "A"], "answer": 3, "explanation": "Order: Mon-M, Mon-E, Wed-M, Wed-E, Fri-M, Fri-E. If C were Wed-M, the sessions two away would be mornings, so C = Wed-E and E = Mon-E or Fri-E; F follows E, so E = Mon-E, F = Wed-M. B = Mon-M, and A before D gives A = Fri-M, D = Fri-E.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-65", "question": "Seven boxes A to G are stacked one above another, position 1 being the bottom. C is immediately above F. Exactly two boxes are kept between F and B. B is at an odd-numbered position above position 3. D is at the top. As many boxes are kept between B and D as between E and C. G is kept above A. Which box is exactly in the middle of the stack?", "options": ["B", "A", "C", "G"], "answer": 1, "explanation": "D = 7, so B = 5, F = 2, C = 3. One box lies between B and D, so one lies between E and C: E = 1. A and G take 4 and 6 with G higher: A = 4, the middle.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-66", "question": "Some persons sit in a row facing north. P sits sixth from the left end, and Q sits third to the right of P. Exactly four persons sit between Q and the right end. R sits third to the left of P. S sits to the immediate left of the person who sits exactly midway between R and Q. What is S's position from the right end?", "options": ["9th", "11th", "8th", "10th"], "answer": 3, "explanation": "P = 6, Q = 9, so the row has 9 + 4 + 1 = 14 persons. R = 3; midway between 3 and 9 is seat 6 (P), so S = 5. From the right: 14 − 5 + 1 = 10th.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-67", "question": "Eight persons A to H sit around a circular table facing away from the centre. B sits third to the right of A, and D sits opposite B. E sits second to the left of D. C sits to the immediate right of A. F is an immediate neighbour of B. H sits to the immediate left of E. Who sits third to the left of F?", "options": ["D", "G", "E", "H"], "answer": 0, "explanation": "Facing outside, right is clockwise. Seats clockwise from A = 0: B = 3, D = 7, E = 5, C = 1, H = 4; F next to B takes 2 and G = 6. Clockwise: A, C, F, B, H, E, G, D. Third to the left (anticlockwise) of F: C, A, then D.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "reason-seating-puzzles-68", "question": "Eight persons A to H sit around a circular table; four face the centre and four face outside. A faces the centre, and C sits third to the left of A. E sits opposite A and faces the same direction as C. B sits second to the right of E. G sits to the immediate left of B and faces outside. D is an immediate neighbour of A and faces outside. F sits second to the left of C. H faces the same direction as A. The two immediate neighbours of C face opposite directions. How many of these statements are true? I. B faces outside. II. F sits third to the right of A. III. H sits to the immediate left of F. IV. D sits opposite E.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Seats clockwise from A = 0: C = 3, E = 4. If C and E faced outside, B = 6, F = 1, D = 7, G = 5, H = 2 and at most A, F, H could face the centre, not four. So C and E face the centre: B = 2, F = 5; G left of B must be 1, so B faces outside; D = 7, H = 6. Centre: A, C, E, H; outside: G, B, F, D. I and II are true; F's left is E, so III is false, and D is opposite C, so IV is false.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-69", "question": "A building has four floors, numbered 1 (bottom) to 4, with a west flat and an east flat on each floor; each flat is directly above the flat on the same side of the floor below. Eight persons A to H live there, one per flat. D lives in an east flat on an odd-numbered floor above floor 1. A lives directly below D. G lives on the same floor as A, and H lives directly above G. C and E live on the same floor, C in the west flat. F lives in an east flat on a floor above A's. How many of these statements are true? I. B lives directly above H. II. E lives in the east flat of floor 1. III. G lives directly above C. IV. F and A live on the same floor.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "D = 3-East, A = 2-East, G = 2-West, H = 3-West. F (east, above floor 2) = 4-East. C and E need a floor with both flats free: floor 1, C west, E east. B = 4-West. I, II and III are true; F is on floor 4 and A on floor 2, so IV is false.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-70", "question": "Six persons P, Q, R, S, T and U have meetings on six dates: the 8th and 19th of March, June and September of one year, one per date. Each likes a different fruit: apple, banana, grape, kiwi, mango and papaya. S's meeting is on the 19th of a month with 30 days. Exactly two meetings fall between S's and that of the kiwi-lover, whose meeting is in March. Q meets immediately before S and likes apple. U meets in the same month as the kiwi-lover but does not like kiwi. The mango-lover meets immediately after the grape-lover. T meets after R, and P does not meet in September. S does not like grape, and U does not like papaya. Who likes papaya, and when is that person's meeting?", "options": ["U – 19 March", "R – 8 September", "S – 19 June", "T – 19 September"], "answer": 2, "explanation": "Order: 8 Mar, 19 Mar, 8 Jun, 19 Jun, 8 Sep, 19 Sep. Kiwi three places from S and in March gives S = 19 Jun, kiwi = 8 Mar. Q = 8 Jun (apple), U = 19 Mar, P = 8 Mar (kiwi), R = 8 Sep, T = 19 Sep. Grape–mango must be S–R or R–T; S is not grape, so R grape, T mango. U is not papaya, so U banana and S papaya.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-71", "question": "Eight seats in a row are numbered 1 to 8 from west to east, and J, K, L, M, N, O, P and Q sit on them; some face north and some face south. K sits at the west end facing north. M sits third to the right of K and faces south. P sits second to the left of M and faces the same direction as K. Exactly one person sits between P and Q, and Q faces opposite to P. N sits to the immediate right of Q. L is an immediate neighbour of K. O sits to the immediate left of M. Both immediate neighbours of M face the same direction as M. N faces north, and L faces opposite to N. How many persons face north, and who sits third to the left of L?", "options": ["Four; J", "Three; O", "Three; M", "Two; O"], "answer": 1, "explanation": "K = 1 faces north, so M = 4. M faces south (left = east): P = 6, O = 5. Q is 4 or 8, so Q = 8, facing south (right = west): N = 7. L = 2, J = 3. J and O face south like M; N faces north and L south. North-facing: K, P, N = three. L faces south, so third to its left (east) is seat 5, O.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-72", "question": "Two parallel rows have five seats each, numbered 1 to 5 from west to east. A, B, C, D and E sit in row 1 facing south, and P, Q, R, S and T sit in row 2 facing north, so each person faces one person of the other row. B sits second from the east end. Q faces the person who sits to the immediate right of B. S sits second to the left of Q, and D faces S. E sits neither at an end nor next to D. A sits at an end, and T faces A. R sits to the immediate left of T. Who faces the person who sits second to the right of A?", "options": ["R", "P", "S", "Q"], "answer": 3, "explanation": "B = 4; B faces south, so its right is west: seat 3, so Q = 3. Q faces north, so its left is west: S = 1, D = 1. E (not an end, not next to D) = 3; A = 5, C = 2. T = 5, R = 4 (left of T is west), P = 2. Second to the right (west) of A is seat 3, E, who faces Q.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-73", "question": "Eight persons A to H sit around a rectangular table facing the centre: one person at each shorter end and three along each longer side, each person on a long side directly facing one person on the other. A sits at one end and C at the other end. D sits second to the right of A, and F sits directly opposite D. G sits to the immediate left of D, and B sits directly opposite G. E sits to the immediate right of C. Who sits directly opposite the person who sits to the immediate right of D?", "options": ["E", "B", "H", "F"], "answer": 0, "explanation": "Label seats clockwise from A = 0: 1, 2, 3 on one side, C at 4, then 5, 6, 7; seat 1 faces 7, 2 faces 6, 3 faces 5. D = 6 (right = anticlockwise), F = 2, G = 7, B = 1, E = 3 and H = 5. D's right is H (5), who faces E (3).", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-74", "question": "Seven persons J, K, L, M, N, O and P were born in 1968, 1973, 1979, 1984, 1988, 1995 and 2000, one in each year. M was born in a leap year after 1980, and the difference between the ages of M and O is 11 years. J is younger than M, and J's age in 2024 is a multiple of 4. P is younger than J. O's age in 2024 is a prime number. L's age in 2024 is a multiple of 9. K is younger than N. Taking ages in 2024, how many persons are older than J, and what is the sum of the ages of K and O?", "options": ["Three; 80", "Four; 76", "Five; 85", "Four; 80"], "answer": 3, "explanation": "Of the leap years 1984, 1988 and 2000, only 1984 has years 11 apart (1973, 1995): M = 1984. J younger than M with age divisible by 4: 1988 (36) or 2000 (24); P is younger, so J = 1988. O's age is 51 (not prime) or 29 (prime), so O = 1995, P = 2000. Of 56, 51, 45, only 45 is a multiple of 9: L = 1979; K = 1973, N = 1968. Older than J: N, K, L, M = four; 51 + 29 = 80.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-75", "question": "Seven persons A to G live on floors 1 (lowest) to 7, one per floor, each from a different city: Agra, Bhopal, Chennai, Delhi, Indore, Jaipur and Kochi. The person from Kochi lives on an odd-numbered floor below floor 4, and exactly two persons live between that person and G. A lives immediately above the person from Kochi. The person from Delhi lives on the top floor, and E lives immediately below that person. D lives on an odd-numbered floor below G. B is from Jaipur and lives below C. F is from Indore, does not live on floor 1 and lives below B. Neither A nor G is from Agra, and the person from Chennai lives below the person from Bhopal. How many of these statements are true? I. E is from Agra. II. The person from Indore lives immediately above A. III. G lives exactly in the middle of the building. IV. Three persons live between D and G.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "E = 6. Kochi is on 1 or 3 and G three floors away; G = 6 is taken, so G = 4, Kochi = 1, A = 2. Floor 7 (Delhi) cannot be B, F or D, so C = 7; then F below B with F not on 1 gives F = 3, B = 5, D = 1 (Kochi). E is from Agra, A Chennai, G Bhopal. I, II and III are true; only two persons (A, F) live between D and G, so IV is false.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-76", "question": "Eight persons A to H sit around a circular table facing the centre. E sits third to the left of B. Only one person sits between E and H, and H is not an immediate neighbour of B. A sits opposite H. C sits to the immediate right of E. G is not an immediate neighbour of H. F sits second to the left of C. Three of the following four pairs are alike in the way the second person sits relative to the first. Which pair does not belong to the group?", "options": ["B, C", "A, E", "E, H", "F, B"], "answer": 3, "explanation": "Seats clockwise from B = 0: E = 3; H is 1 or 5 and not next to B, so H = 5; A = 1; C = 2; G avoids 4 and 6, so G = 7; F = 4, D = 6. Clockwise: B, A, C, E, F, H, D, G. In B–C, A–E and E–H the second person sits second to the left of the first; B sits fourth from F.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-77", "question": "Six boxes P, Q, R, S, T and U are stacked one above another, position 1 being the bottom, and each is a different colour: red, blue, green, yellow, white and black. R is fourth from the top. Exactly one box is kept between R and the green box, which is not at the bottom. P is immediately below S. The blue box is immediately below R. The red box is at the top and the white box at the bottom. Q is kept below T. U is above R and is not green. R is not yellow. S is neither blue nor at the top. Which box is yellow, and how many boxes are kept between it and the white box?", "options": ["P; two", "U; two", "P; three", "Q; one"], "answer": 0, "explanation": "R = 3, green = 5, blue = 2, red = 6, white = 1; R is not yellow, so R is black and position 4 is yellow. S cannot be at 2 (blue) or 6, so P–S = 4–5. U above R takes 6; Q below T gives Q = 1, T = 2. P is yellow at 4, with T and R (two boxes) between it and the white box.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-78", "question": "Seven persons A to G sit in a row facing north, and each likes a different sport: cricket, hockey, tennis, chess, golf, polo and squash. The chess-lover sits third from the left end, and D sits second to the right of the chess-lover. Exactly two persons sit between D and the golf-lover. B likes hockey and sits to the immediate left of D. The tennis-lover sits to the immediate right of D. F likes squash and sits next to the golf-lover. A sits at an end and does not like polo. G likes neither chess nor golf. E sits to the right of C. Who likes polo, and who sits second to the left of the tennis-lover?", "options": ["A; B", "D; E", "D; B", "G; C"], "answer": 2, "explanation": "Chess = 3, D = 5, golf = 2, B = 4, tennis = 6. F (squash) next to golf cannot be 3, so F = 1 and A = 7. Cricket and polo remain for D and A; A is not polo, so D likes polo. G avoids 2 and 3, so G = 6 (tennis), C = 2, E = 3. Second to the left of G is seat 4, B.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-79", "question": "A building has three floors, numbered 1 (bottom) to 3, each with three flats in a line: flat 1 (west), flat 2 (middle) and flat 3 (east); each flat is directly above the flat with the same number below. Nine persons A to I live there, one per flat. E lives in the middle flat of floor 2, and A lives directly above E. G lives in the east flat of E's floor, and B lives directly below G. H lives in a west flat but not on A's floor, and I lives directly below H. C and D live on the same floor, D in a west flat. F lives on floor 1. Who lives directly above G, and who lives in the middle flat of floor 1?", "options": ["A; I", "C; F", "D; F", "C; B"], "answer": 1, "explanation": "E = 2-middle, A = 3-middle, G = 2-east, B = 1-east. H needs a flat below it and is not on floor 3, so H = 2-west, I = 1-west, and F takes 1-middle. C and D share floor 3: D = 3-west, C = 3-east, directly above G.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-80", "question": "Eight persons J, K, L, M, N, O, P and Q sit around a circular table facing the centre. J and L sit opposite each other. N sits second to the left of L, and P sits third to the right of N. K is an immediate neighbour of J but not of N. Q sits to the immediate right of N. O is not an immediate neighbour of N. If J and P interchange their seats, who will then sit second to the right of P?", "options": ["M", "Q", "N", "K"], "answer": 2, "explanation": "Seats clockwise from J = 0: L = 4, N = 6, P = 3; K is next to J but not N, so K = 1; Q = 5; O avoids 7, so O = 2 and M = 7. Clockwise: J, K, O, P, L, Q, N, M. After the swap P is at seat 0; second to its right (anticlockwise) is seat 6, N.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-81", "question": "Nine seats in a row are numbered 1 to 9 from left to right, and six persons A to F sit on six of them facing north; three seats are vacant. D sits at the extreme right end. B sits second to the left of D, and the seat between them is vacant. A sits fourth to the left of B. Exactly one of the two seats next to A is vacant. E sits to the immediate right of A. C sits at the extreme left end. F is not an immediate neighbour of E. How many persons and how many vacant seats are there between C and B?", "options": ["Three persons and two vacant seats", "Four persons and one vacant seat", "Three persons and one vacant seat", "Two persons and three vacant seats"], "answer": 0, "explanation": "D = 9, B = 7, seat 8 vacant, A = 3, E = 4, so seat 2 is the vacant neighbour of A; C = 1. F takes 5 or 6 and is not next to E, so F = 6 and seat 5 is vacant. Between seats 1 and 7: vacant 2, A, E, vacant 5, F — three persons and two vacant seats.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-82", "question": "Six persons P, Q, R, S, T and U were born in different months of the same year: January, March, April, June, September and November, one in each. R was born in a month with 30 days, and exactly two of them were born between R and T. T was born in a month with 31 days, and Q was born in the very next month of this list after T. S was born in a month with 30 days, but not in the month just after Q's in the list. P was born after S, and U was not born in November. Who was born in April, and how many persons were born between U and P?", "options": ["Q; three", "U; three", "R; one", "U; two"], "answer": 3, "explanation": "T is January or March and R is three places later: (Jan, Jun) or (Mar, Sep). If T = Mar, Q = Apr and S (30 days, not June) = Nov, leaving no month after S for P, so T = Jan, Q = Mar, R = Jun. S cannot be April, and P is after S, so S = Sep, P = Nov, U = Apr. Between U (Apr) and P (Nov): R and S, two.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-83", "question": "Six persons A to F sit around a circular table facing the centre, and each has a different profession: doctor, engineer, lawyer, pilot, teacher and writer. The doctor sits opposite A, and B sits to the immediate left of the doctor. The lawyer sits second to the left of B. C is the pilot and sits opposite B. D is not the doctor and sits next to A. The teacher sits to the immediate right of the engineer. E is the writer. Who is the teacher, and who sits opposite the engineer?", "options": ["D; E", "B; E", "B; F", "F; C"], "answer": 1, "explanation": "Seats clockwise from A = 0: doctor = 3, B = 4, lawyer = seat 0, so A is the lawyer. C (pilot) = 1. D next to A = 5. E (writer) cannot take the doctor's seat, so E = 2, F = 3 (doctor). The teacher sits anticlockwise of the engineer, so D = engineer, B = teacher. Opposite D (5) is seat 2, E.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-84", "question": "Eight persons A to H sit around a square table: four sit at the corners facing the centre and four sit at the middle of the sides facing outside. A sits at a corner. E sits third to the left of A. B sits second to the right of E. G sits opposite E, and C sits to the immediate left of G. H is not an immediate neighbour of A. D sits at a corner next to B. How many of these statements are true? I. F faces outside. II. H sits second to the left of E. III. C sits opposite F. IV. D sits to the immediate right of E.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 2, "explanation": "Seats clockwise from A = 0; even seats are corners (facing in), odd seats middles (facing out). E = 3, facing out, so its right is clockwise: B = 5. G = 7, its left is anticlockwise: C = 6. D (corner next to B) = 4, H (not next to A) = 2, F = 1. I and IV are true; E's second left is F, not H, and C is opposite H, not F.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "reason-seating-puzzles-85", "question": "Six persons A to F sit in a row facing north, and their ages are 21, 24, 27, 30, 33 and 36 years, all different. The person aged 30 sits third from the left end, and B sits second to the right of that person. The eldest sits at an end, and exactly one person sits between the eldest and E. E is 6 years younger than B. A sits to the immediate left of E. F sits at an end, is not the eldest and is older than B. C is younger than D and sits to the left of D. What is the sum of the ages of the two persons at the ends, and who is the youngest?", "options": ["69; E", "69; C", "66; E", "63; A"], "answer": 0, "explanation": "The 30-year-old is at 3 and B at 5. If the eldest sat at 1, E would be the 30-year-old at 3 and B would have to be 36, impossible. So the eldest is at 6, E = 4, A = 3 (30). F (not eldest) = 1; C = 2, D = 6 (36). E = B − 6: B 27, E 21 or B 33, E 27; F is older than B, so B = 27, E = 21, F = 33, C = 24. Ends: 33 + 36 = 69; youngest E.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
];

export default questions;
